patch:
diff --git a/repro/windows-different-drive.js b/repro/windows-different-drive.js
new file mode 100644
index 0000000..c2a207c
--- /dev/null
+++ b/repro/windows-different-drive.js
@@ -0,0 +1,77 @@
+/* eslint-disable no-console, no-underscore-dangle, @eslint-community/eslint-comments/disable-enable-pair -- standalone repro script */
+/**
+ * Repro for "files on a different drive are not ignored on Windows".
+ *
+ * Usage: node repro/windows-different-drive.js [win32|posix]
+ *
+ * "win32" (default) SIMULATES Windows on a non-Windows host: Node's `path`
+ * module is replaced (for CommonJS requires) with `path.win32` and process.cwd() returns C:\Project
+ * before ESLint is loaded. "posix" runs the equivalent paths natively as a control.
+ */
+"use strict";
+
+const mode = process.argv[2] || "win32";
+const path = require("node:path");
+
+let cwd, cases;
+
+if (mode === "win32") {
+    const Module = require("node:module");
+    const originalLoad = Module._load;
+
+    // Userland CommonJS modules (ESLint and its dependencies) get `path.win32`.
+    Module._load = function(request, ...rest) {
+        if (request === "path" || request === "node:path") {
+            return path.win32;
+        }
+        return originalLoad.call(this, request, ...rest);
+    };
+    cwd = "C:\\Project";
+    process.cwd = () => cwd;
+    cases = {
+        "inside cwd": "C:\\Project\\foo.js",
+        "same drive, outside cwd": "C:\\Other\\foo.js",
+        "different drive (reported)": "F:\\foo.js"
+    };
+} else {
+    cwd = "/project";
+    cases = {
+        "inside cwd": "/project/foo.js",
+        "outside cwd": "/other/foo.js"
+    };
+    process.cwd = () => cwd;
+}
+
+const { Linter, ESLint } = require("../lib/api");
+
+(async () => {
+    console.log(`mode=${mode} cwd=${process.cwd()}`);
+    console.log(`path.win32.relative("C:\\\\Project", "F:\\\\foo.js") = ${JSON.stringify(path.win32.relative("C:\\Project", "F:\\foo.js"))}\n`);
+
+    const linter = new Linter({ configType: "flat", cwd });
+    const eslint = new ESLint({ cwd, overrideConfigFile: true, overrideConfig: { rules: { "no-undef": "error" } } });
+
+    for (const [label, filename] of Object.entries(cases)) {
+        const linterMsgs = linter.verify("foo()", { rules: { "no-undef": "error" } }, filename)
+            .map(m => `${m.ruleId ?? "-"}: ${m.message}`);
+        const [result] = await eslint.lintText("foo()", { filePath: filename, warnIgnored: true });
+        const eslintMsgs = result.messages.map(m => `${m.ruleId ?? "-"}: ${m.message}`);
+        const ignored = await eslint.isPathIgnored(filename);
+
+        console.log(`${label}: ${filename}`);
+        console.log(`  Linter#verify:         ${JSON.stringify(linterMsgs)}`);
+        console.log(`  ESLint#lintText:       ${JSON.stringify(eslintMsgs)}`);
+        console.log(`  ESLint#isPathIgnored:  ${ignored}`);
+
+        if (label.includes("outside") && !ignored) {
+            process.exitCode = 1;
+        }
+        if (label.includes("different drive") && !ignored) {
+            console.log("  BUG: file on a different drive was linted instead of ignored");
+            process.exitCode = 1;
+        }
+    }
+})().catch(err => {
+    console.error(err);
+    process.exitCode = 1;
+});
